#[derive(Debug, Clone, PartialEq, Eq)]
pub enum ControlMessage {
    RequestKeyFrame,
    StartStream,
    StopStream,
    Disconnect,
    Ping,
    Pong,
    BitrateAdjust(BitrateAdjust),
    StreamConfigRequest(StreamConfigurationRequest),
    StreamConfigResponse(StreamConfigurationResponse),
    StreamConfigReject(StreamConfigurationReject),
    StreamConfigError(StreamConfigurationError),
    ClipboardSyncRequest(ClipboardSyncRequest),
    ClipboardSyncUpdate(ClipboardSyncUpdate),
    ClipboardSyncError(ClipboardSyncError),
}

impl ControlMessage {
    pub const fn message_type(&self) -> ControlMessageType {
        match self {
            Self::RequestKeyFrame => ControlMessageType::RequestKeyFrame,
            Self::StartStream => ControlMessageType::StartStream,
            Self::StopStream => ControlMessageType::StopStream,
            Self::Disconnect => ControlMessageType::Disconnect,
            Self::Ping => ControlMessageType::Ping,
            Self::Pong => ControlMessageType::Pong,
            Self::BitrateAdjust(_) => ControlMessageType::BitrateAdjust,
            Self::StreamConfigRequest(_) => ControlMessageType::StreamConfigRequest,
            Self::StreamConfigResponse(_) => ControlMessageType::StreamConfigResponse,
            Self::StreamConfigReject(_) => ControlMessageType::StreamConfigReject,
            Self::StreamConfigError(_) => ControlMessageType::StreamConfigError,
            Self::ClipboardSyncRequest(_) => ControlMessageType::ClipboardSyncRequest,
            Self::ClipboardSyncUpdate(_) => ControlMessageType::ClipboardSyncUpdate,
            Self::ClipboardSyncError(_) => ControlMessageType::ClipboardSyncError,
        }
    }
}

impl WireCodec for ControlMessage {
    fn encode(&self) -> Result<Vec<u8>, CodecError> {
        let mut output = vec![self.message_type() as u8];
        let body = match self {
            Self::RequestKeyFrame
            | Self::StartStream
            | Self::StopStream
            | Self::Disconnect
            | Self::Ping
            | Self::Pong => return Ok(output),
            Self::BitrateAdjust(value) => value.encode()?,
            Self::StreamConfigRequest(value) => value.encode()?,
            Self::StreamConfigResponse(value) => value.encode()?,
            Self::StreamConfigReject(value) => value.encode()?,
            Self::StreamConfigError(value) => value.encode()?,
            Self::ClipboardSyncRequest(value) => value.encode()?,
            Self::ClipboardSyncUpdate(value) => value.encode()?,
            Self::ClipboardSyncError(value) => value.encode()?,
        };
        output.extend_from_slice(&body);
        Ok(output)
    }

    fn decode(input: &[u8]) -> Result<Self, CodecError> {
        let mut decoder = Decoder::new(input);
        let message_type = ControlMessageType::try_from(decoder.u8("control message type")?)?;
        let body = decoder.take_remaining();
        match message_type {
            ControlMessageType::RequestKeyFrame => Ok(Self::RequestKeyFrame),
            ControlMessageType::StartStream => Ok(Self::StartStream),
            ControlMessageType::StopStream => Ok(Self::StopStream),
            ControlMessageType::Disconnect => Ok(Self::Disconnect),
            ControlMessageType::Ping => Ok(Self::Ping),
            ControlMessageType::Pong => Ok(Self::Pong),
            ControlMessageType::BitrateAdjust => {
                Ok(Self::BitrateAdjust(BitrateAdjust::decode(body)?))
            }
            ControlMessageType::StreamConfigRequest => Ok(Self::StreamConfigRequest(
                StreamConfigurationRequest::decode(body)?,
            )),
            ControlMessageType::StreamConfigResponse => Ok(Self::StreamConfigResponse(
                StreamConfigurationResponse::decode(body)?,
            )),
            ControlMessageType::StreamConfigReject => Ok(Self::StreamConfigReject(
                StreamConfigurationReject::decode(body)?,
            )),
            ControlMessageType::StreamConfigError => Ok(Self::StreamConfigError(
                StreamConfigurationError::decode(body)?,
            )),
            ControlMessageType::ClipboardSyncRequest => Ok(Self::ClipboardSyncRequest(
                ClipboardSyncRequest::decode(body)?,
            )),
            ControlMessageType::ClipboardSyncUpdate => Ok(Self::ClipboardSyncUpdate(
                ClipboardSyncUpdate::decode(body)?,
            )),
            ControlMessageType::ClipboardSyncError => {
                Ok(Self::ClipboardSyncError(ClipboardSyncError::decode(body)?))
            }
        }
    }
}

use std::io::{self, BufRead, Write};
use std::sync::mpsc;

use anyhow::{bail, Context, Result};
use clap::Parser;
use erd_host::{
    accessibility_is_trusted, random_pin, request_accessibility, ConsentPrompt, HostConfig,
    HostServer, PairingStore,
};
use tracing_subscriber::EnvFilter;

#[derive(Debug, Parser)]
#[command(
    name = "erd-host",
    version,
    about = "EclipticRD v3 macOS screen streaming host",
    long_about = "EclipticRD v3 macOS screen streaming host.\n\nFirst run: macOS prompts for Screen Recording and Accessibility. Grant both in System Settings > Privacy & Security, then relaunch the host. Screen Recording is required for capture; Accessibility is required for remote input injection."
)]
struct Cli {
    /// Use this exact 8-digit bootstrap PIN.
    #[arg(long, value_name = "PIN", conflicts_with = "pin")]
    bootstrap_pin: Option<String>,

    /// Generate and display a fresh 8-digit bootstrap PIN (`--pin generate`).
    #[arg(long, value_name = "generate", conflicts_with = "bootstrap_pin")]
    pin: Option<String>,

    /// List persisted paired devices and exit.
    #[arg(long, conflicts_with_all = ["revoke", "bootstrap_pin", "pin"])]
    list_paired: bool,

    /// Revoke one pairing ID and exit.
    #[arg(long, value_name = "ID", conflicts_with_all = ["list_paired", "bootstrap_pin", "pin"])]
    revoke: Option<String>,

    /// LAN HEVC bitrate in Mbps. Accepted range: 50 through 150.
    /// Without this flag the compatibility default is 8 Mbps.
    #[arg(long, value_name = "MBPS", value_parser = clap::value_parser!(u32).range(50..=150))]
    lan_bitrate_mbps: Option<u32>,

    /// Disable ScreenCaptureKit host-audio capture.
    #[arg(long)]
    no_audio: bool,
}

fn main() -> Result<()> {
    tracing_subscriber::fmt()
        .with_env_filter(
            EnvFilter::try_from_default_env().unwrap_or_else(|_| EnvFilter::new("info")),
        )
        .init();

    let cli = Cli::parse();
    let store = PairingStore::host_default()?;
    if cli.list_paired {
        let mut records = store.load_all()?;
        records.sort_by(|left, right| right.added_at_unix_ms.cmp(&left.added_at_unix_ms));
        if records.is_empty() {
            println!("No paired devices.");
        } else {
            for record in records {
                println!(
                    "{}\t{}\t{}",
                    record.id, record.name, record.added_at_unix_ms
                );
            }
        }
        return Ok(());
    }
    if let Some(id) = cli.revoke {
        if store.revoke(&id)? {
            println!("Revoked pairing {id}");
        } else {
            bail!("pairing ID not found: {id}");
        }
        return Ok(());
    }

    let pin = match (cli.bootstrap_pin, cli.pin.as_deref()) {
        (Some(pin), None) => validate_pin(pin)?,
        (None, Some("generate")) | (None, None) => random_pin(),
        (None, Some(other)) => bail!("--pin accepts only 'generate', got '{other}'"),
        (Some(_), Some(_)) => unreachable!("clap enforces conflicts"),
    };

    onboard_permissions();

    let (consent_tx, consent_rx) = mpsc::channel::<ConsentPrompt>();
    std::thread::Builder::new()
        .name("erd-host-consent".into())
        .spawn(move || consent_loop(consent_rx))
        .context("failed to start consent UI channel")?;

    let mut config = HostConfig::macos_default(Some(pin.clone()), store)?;
    config.capture_audio = !cli.no_audio;
    config.consent_sender = Some(consent_tx);
    if let Some(mbps) = cli.lan_bitrate_mbps {
        config.bitrate = mbps * 1_000_000;
    }

    let server = HostServer::bind(config)?;
    println!("EclipticRD bootstrap PIN: {pin}");
    println!("TCP listening on {}", server.tcp_addr()?);
    println!("UDP listening on {}", server.udp_addr()?);
    println!("Pairing approval requests will appear in this terminal.");
    server.serve()?;
    Ok(())
}

fn validate_pin(pin: String) -> Result<String> {
    if pin.len() != 8 || !pin.bytes().all(|byte| byte.is_ascii_digit()) {
        bail!("bootstrap PIN must be exactly 8 decimal digits");
    }
    Ok(pin)
}

fn consent_loop(receiver: mpsc::Receiver<ConsentPrompt>) {
    let stdin = io::stdin();
    let mut lines = stdin.lock().lines();
    while let Ok(prompt) = receiver.recv() {
        print!("Approve pairing for '{}' [y/N]? ", prompt.client_name);
        let _ = io::stdout().flush();
        let approved = lines
            .next()
            .and_then(Result::ok)
            .is_some_and(|line| matches!(line.trim().to_ascii_lowercase().as_str(), "y" | "yes"));
        prompt.respond(approved);
    }
}


