    fn bind_with_media(
        config: HostConfig,
        media_source: Arc<dyn MediaSource>,
    ) -> Result<Self, SessionError> {
        if config
            .bootstrap_pin
            .as_ref()
            .is_some_and(|pin| pin.len() != 8 || !pin.bytes().all(|byte| byte.is_ascii_digit()))
