        let pairing_deadline = config
            .bootstrap_pin
            .as_ref()
            .map(|_| Instant::now() + config.pairing_window);
        if pairing_deadline.is_some() {
            lockout.lock().expect("lockout poisoned").begin_pairing();
        }
        Ok(Self {
            config,
            tcp_listener,
            udp_socket,
            media_source,
            lockout,
            pairing_deadline,
        })
    }

